def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 500:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    slots = int(supply // WATER_REQ)
    if slots < 0:
        slots = 0

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    if hp <= 2 or no_water >= 2:
        emergency = max(62.0, highest_prev + 3.0)
        return float(min(budget, emergency))

    if hp <= 4 or no_water >= 1:
        strong = max(42.0, min(68.0, highest_prev * 0.72 + 6.0))
        return float(min(budget, strong))

    if slots >= 2:
        base = 16.0
        if highest_prev > 110:
            base = 12.0
        elif highest_prev > 70:
            base = 14.0
        elif avg_prev < 35:
            base = 18.0
        if urgent_opp >= 2:
            base += 4.0
        return float(min(budget, base))

    contest = 24.0
    if highest_prev > 110:
        contest = 20.0
    elif highest_prev > 70:
        contest = 26.0
    else:
        contest = max(24.0, avg_prev + 2.0)

    if rich_opp >= 2:
        contest -= 3.0
    if urgent_opp >= 2:
        contest += 6.0

    contest = max(15.0, min(55.0, contest))
    return float(min(budget, contest))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 10.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0
    if my_status['hp'] < 4:
        return min(my_status['budget'], max(avg_bid * 1.2, DAILY_SALARY * 0.8))
    return min(my_status['budget'], max(avg_bid * 0.95, DAILY_SALARY * 0.5))
